import fs from "node:fs";
import path from "node:path";
import { parseArgs } from "node:util";
import { TfidfClassifier } from "./classifiers/tfidf.js";
import { importDataset } from "./dataset.js";

/**
 * Trains the tf-idf classifier on a whole labeled dataset and writes the model file the server's
 * local classifier loads (ADR-001 task 5). The dataset is private, so the file is generated by
 * its owner and installed next to the database; it is never committed.
 *
 *   npx tsx scripts/release-benchmark/export-model.ts --dataset releases-labeled.csv --out release-classifier.json
 *
 * Evaluate with run.ts first: this trains on every row and leaves nothing to test against.
 */
const { values } = parseArgs({
  options: {
    dataset: { type: "string" },
    out: { type: "string", default: "release-classifier.json" },
    version: { type: "string" },
    "title-aware": { type: "boolean", default: false },
    seed: { type: "string", default: "42" },
  },
});

if (!values.dataset) {
  console.error("Missing --dataset <file.csv|file.jsonl>");
  process.exit(2);
}
const format = values.dataset.endsWith(".jsonl") ? "jsonl" : "csv";
const { records } = importDataset(fs.readFileSync(values.dataset, "utf8"), format);
if (records.length === 0) {
  console.error("The dataset has no usable records.");
  process.exit(2);
}

const classifier = new TfidfClassifier({
  titleAware: values["title-aware"] ?? false,
  seed: Number(values.seed),
  threshold: 0,
});
classifier.train(records);
const version =
  values.version ?? `tfidf-${new Date().toISOString().slice(0, 10)}-n${records.length}`;
const model = classifier.toModelFile(version);
fs.mkdirSync(path.dirname(path.resolve(values.out ?? "")), { recursive: true });
fs.writeFileSync(values.out ?? "", JSON.stringify(model));
console.log(
  `Wrote ${values.out}: ${version}, ${records.length} rows, ${model.vocab.length} features, ${(
    fs.statSync(values.out ?? "").size / 1024
  ).toFixed(0)} KB.`
);
